<?php namespace DomainSystem\Plugins\auth\Repositories; use DomainSystem\Plugins\Database\Connection; use DomainSystem\Plugins\auth\Contracts\UserRepositoryInterface; class SqliteUserRepository implements UserRepositoryInterface { private \PDO $db; public function __construct(Connection $connection) { $this->db = $connection->getPdo(); } public function findByEmail(string $email): ?array { $stmt = $this->db->prepare("SELECT * FROM users WHERE email = :email LIMIT 1"); $stmt->execute([":email" => $email]); $result = $stmt->fetch(\PDO::FETCH_ASSOC); return $result ?: null; } public function findById(int $id): ?array { $stmt = $this->db->prepare("SELECT * FROM users WHERE id = :id LIMIT 1"); $stmt->execute([":id" => $id]); $result = $stmt->fetch(\PDO::FETCH_ASSOC); return $result ?: null; } public function findDoctorByUserId(int $userId): ?array { $stmt = $this->db->prepare("SELECT * FROM doctors WHERE user_id = :user_id LIMIT 1"); $stmt->execute([":user_id" => $userId]); $result = $stmt->fetch(\PDO::FETCH_ASSOC); return $result ?: null; } public function updateTwoFactor(int $userId, string $type, ?string $secret): void { $stmt = $this->db->prepare("UPDATE users SET two_factor_type = :type, two_factor_secret = :secret WHERE id = :id"); $stmt->execute([":type" => $type, ":secret" => $secret, ":id" => $userId]); } public function getAllUsers(): array { $stmt = $this->db->query("SELECT * FROM users"); return $stmt->fetchAll(\PDO::FETCH_ASSOC); } public function getAllDoctors(): array { $stmt = $this->db->query("SELECT * FROM doctors"); return $stmt->fetchAll(\PDO::FETCH_ASSOC); } public function createUser(array $data): void { $fields = implode(", ", array_keys($data)); $placeholders = ":" . implode(", :", array_keys($data)); $stmt = $this->db->prepare("INSERT INTO users ($fields) VALUES ($placeholders)"); $params = []; foreach ($data as $k => $v) { $params[":$k"] = $v; } $stmt->execute($params); } public function updateTwoFactorSecret(int $userId, ?string $secret): void { $stmt = $this->db->prepare("UPDATE users SET two_factor_secret = :secret WHERE id = :id"); $stmt->execute([":secret" => $secret, ":id" => $userId]); } public function updatePassword(int $userId, string $hash): void { $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id"); $stmt->execute([":password" => $hash, ":id" => $userId]); } }
